// ── FiveM resource templates and validation ──
// Standard file structure the agent follows when writing FiveM resources.

const FXMANIFEST_TEMPLATE = (name, description = "") => `fx_version 'cerulean'
game 'gta5'

name '${name}'
description '${description}'
author 'Dev Agent'

client_scripts {
    'client.lua'
}

server_scripts {
    'server.lua'
}

shared_scripts {
    '@ox_lib/init.lua'
}
`;

const CLIENT_LUA_TEMPLATE = (name) => `-- ${name} Client Script
-- Auto-generated by Dev Agent

local QBCore = exports['qb-core']:GetCoreObject()

-- Example: Register a command
RegisterCommand('test${name}', function()
    QBCore.Functions.Notify('${name} client script is working!', 'success')
end, false)

-- Example: Event handler
RegisterNetEvent('${name}:client:test')
AddEventHandler('${name}:client:test', function(data)
    QBCore.Functions.Notify('Received: ' .. json.encode(data), 'primary')
end)

-- Thread example
CreateThread(function()
    while true do
        Wait(5000)
        -- Periodic logic here
    end
end)
`;

const SERVER_LUA_TEMPLATE = (name) => `-- ${name} Server Script
-- Auto-generated by Dev Agent

local QBCore = exports['qb-core']:GetCoreObject()

-- Example: Register a server command
QBCore.Commands.Add('test${name}', 'Test ${name} command', {}, false, function(source, args)
    local Player = QBCore.Functions.GetPlayer(source)
    if Player then
        TriggerClientEvent('${name}:client:test', source, { message = 'Hello from server!' })
    end
end)

-- Example: Callback
QBCore.Functions.CreateCallback('${name}:server:getData', function(source, cb)
    cb({ status = 'ok', timestamp = os.time() })
end)
`;

function validateResource(dirPath, files) {
  const errors = [];
  const warnings = [];

  // Check for fxmanifest.lua
  if (!files.some(f => f.path.endsWith('fxmanifest.lua') || f.path.endsWith('__resource.lua'))) {
    errors.push('Missing fxmanifest.lua or __resource.lua');
  }

  // Check for client or server scripts
  const hasClient = files.some(f => f.path.endsWith('.lua') && f.path.includes('client'));
  const hasServer = files.some(f => f.path.endsWith('.lua') && f.path.includes('server'));
  if (!hasClient && !hasServer) {
    warnings.push('No client.lua or server.lua found');
  }

  // Check fxmanifest content for game declaration
  const fxFile = files.find(f => f.path.endsWith('fxmanifest.lua') || f.path.endsWith('__resource.lua'));
  if (fxFile && fxFile.content) {
    if (!fxFile.content.includes("game '")) {
      errors.push('fxmanifest.lua missing game declaration');
    }
    if (!fxFile.content.includes("fx_version")) {
      warnings.push('fxmanifest.lua missing fx_version');
    }
  }

  return { valid: errors.length === 0, errors, warnings };
}

module.exports = {
  FXMANIFEST_TEMPLATE,
  CLIENT_LUA_TEMPLATE,
  SERVER_LUA_TEMPLATE,
  validateResource,
};